  kind              public.suspicious_kind not null,
  severity          smallint not null default 1 check (severity between 1 and 5),
  details           jsonb not null default '{}'::jsonb,
  ref_type          text,
  ref_id            uuid,
  reviewed_by       uuid references auth.users (id) on delete set null,
